/**
 * Static map of Monzone and the villages around it (Fivizzano, MS): the only
 * module the sim and the renderer import for map data. The map files are generated by `pnpm map`
 * (src/tools/build-map.ts) from OSM and Regione Toscana's CTR and LiDAR; never edit them. Importing
 * this module decodes the global file (`./global.ts`; in the browser the host must have called
 * `provideMap` first); the dense layers (terrain, walls, trees, land cover) live in 2 km tiles that
 * the host hands over as the player moves (`./tiles.ts`), which `heightAt`, `wallsNear` and
 * `treesIn` read.
 *
 * Frame: x = east, y = north, metres from `MAP.origin` (equirectangular,
 * `MAP.mPerDeg`); elevations in metres a.s.l. Polylines and rings are flat
 * `[x0, y0, x1, y1, ...]` arrays rounded to 0.1 m; rings are open, outer rings
 * counter-clockwise (positive signed area), holes clockwise. Angles are radians
 * from +x (east) towards +y (north).
 *
 * Everything here is immutable module content built once at load (plus the
 * query buffers `wallsNear` reuses and the tiles in memory, which no answer depends on), so it is
 * safe in the deterministic sim (no gameplay state lives here).
 *
 * @module map
 */
import { staticGrid } from "../collide.ts"
import type { VehicleModel } from "../vehicles.ts"
import { MAP } from "./global.ts"
import {
  BUILDING_STYLES,
  type BuildingStyle,
  isRoadClass,
  type RailKind,
  type RoadClass,
} from "./kinds.ts"
import type { Railway } from "./railway.ts"
import { cellNodes, type WallKind } from "./tiles.ts"

export { MAP } from "./global.ts"
export {
  AREA_KINDS,
  type AreaKind,
  BUILDING_STYLES,
  type BuildingStyle,
  isAreaKind,
  isDrivable,
  laneOffset,
  RAIL_KINDS,
  RAIL_LIFT,
  type RailKind,
  ROAD_CLASSES,
  type RoadClass,
  TILE,
  TRUNK,
  vergeOf,
} from "./kinds.ts"
export type { LevelCrossing, LinePiece, Platform, RailLine, Railway, Station } from "./railway.ts"
export { type Segment, treesIn, type WallKind, wallsNear } from "./tiles.ts"

/** Play area rectangle, metres. */
interface Bounds {
  readonly minX: number
  readonly minY: number
  readonly maxX: number
  readonly maxY: number
}

/**
 * The terrain lattice: `cols` × `rows` nodes every `cell` m from the south-west node (x0, y0), which
 * span `bounds`. The nodes themselves (integer decimetres) are in the tiles, whose nodes are this
 * lattice's (`./tiles.ts`).
 */
interface Heightmap {
  readonly cell: number
  readonly cols: number
  readonly rows: number
  readonly x0: number
  readonly y0: number
}

/** A tile of the map (`TILE` m square (i, j)): its lowest and highest terrain node, decimetres. */
export interface TileEntry {
  readonly i: number
  readonly j: number
  readonly zmin: number
  readonly zmax: number
}

/**
 * The whole map's terrain and land cover every `cell` (64) m, on a lattice from (x0, y0) on the
 * origin's multiples: each node's height (decimetres, the terrain node there) and the cover of the
 * 4 m cell north-east of it. For hosts reading far from the player, where no tile is in memory
 * (sound paths, shadows, lightning): never for the sim.
 */
export interface Coarse {
  readonly cell: number
  readonly cols: number
  readonly rows: number
  readonly x0: number
  readonly y0: number
  readonly heights: Int16Array
  readonly cover: Uint8Array
}

/** A road piece (OSM highway way clipped to the play area). `cls` narrows with `roadClassOf`. */
export interface Road {
  readonly id: number
  readonly cls: string
  readonly name?: string
  readonly ref?: string
  /** Carriageway width, m. */
  readonly w: number
  readonly surface: string
  readonly oneway?: boolean
  readonly bridge?: boolean
  readonly tunnel?: boolean
  readonly layer?: number
  /** Where people walk, m from the centreline on either side, when the build pulls the verge in off the railway beside it (else `vergeOf`). */
  readonly verge?: number
  /** The OSM vertices plus points on the OSM segments where the elevation profile bends (dips under the rail, crests). */
  readonly pts: ReadonlyArray<number>
  /** Road surface elevation per vertex (m); bridge decks and tunnels are straight between their ends. */
  readonly z: ReadonlyArray<number>
}

/** `style` narrows with `buildingStyleOf`; `tint` is a colour variant 0..3. */
export interface Building {
  readonly id: number
  readonly kind: string
  readonly name?: string
  /** Wall height above `z0`, m. */
  readonly h: number
  /** Lowest terrain under the footprint vertices, m. */
  readonly z0: number
  readonly style: string
  readonly ruins?: boolean
  readonly tint: number
  readonly outer: ReadonlyArray<number>
  readonly holes?: ReadonlyArray<ReadonlyArray<number>>
}

/**
 * A river or stream centreline; `kind` is "river" | "stream". `w` is the water's width and `bed`
 * the gravel bed's half-width (m); the bed is carved `depth`/2 under `z` across `w`. `z` = the
 * built water surface per vertex: monotone downstream except where it dips under an at-grade road
 * (implied culvert); at least 2.5 m under every bridge deck. `area` = the catchment upstream of each
 * vertex, km². `pts` adds points on the OSM segments where the surface bends.
 */
export interface Water {
  readonly id: number
  readonly kind: string
  readonly name?: string
  readonly w: number
  readonly bed: number
  readonly depth: number
  readonly pts: ReadonlyArray<number>
  readonly z: ReadonlyArray<number>
  readonly area: ReadonlyArray<number>
  /** The bed's elevation per vertex (m a.s.l.), baked by the build from the terrain under it (`bedOf` in src/sim/water/channel.ts). */
  readonly floor: ReadonlyArray<number>
}

/**
 * A railway piece: OSM's Lucca–Aulla line moved onto the CTR's surveyed track centrelines (`id` the
 * OSM way), or a track only the CTR has (`id` negative); `z` = the bed under its sleepers per vertex
 * (the rail head is `RAIL_LIFT` higher), bridges and tunnels interpolated between their ends.
 * Tracks meet only at piece ends (switches cut the pieces), so `id` is not unique: the pieces cut
 * from one way (at its switches and where the CTR maps a bridge) share it.
 */
export interface Rail {
  readonly id: number
  /** None on a line's running track; else, from the topology, a `loop` (rejoins other track at both ends) or a `siding` (leads to a dead end). */
  readonly kind?: RailKind
  readonly bridge?: boolean
  readonly tunnel?: boolean
  readonly pts: ReadonlyArray<number>
  readonly z: ReadonlyArray<number>
}

/** Land use polygon: `rings[0]` outer, the rest holes; `kind` is one of `AREA_KINDS` (checked by map.test.ts, narrow with `isAreaKind`). */
export interface Area {
  readonly kind: string
  readonly name?: string
  readonly rings: ReadonlyArray<ReadonlyArray<number>>
}

/** "wall" | "guard_rail" | "cliff" polyline. */
export interface Barrier {
  readonly kind: string
  readonly pts: ReadonlyArray<number>
}

/** Point of interest; `kind` is `key=value` of the OSM tag (or `area:<kind>` for named polygons). */
export interface Poi {
  readonly id: number
  readonly kind: string
  readonly name?: string
  readonly x: number
  readonly y: number
}

/** HUD location label for the disc of radius `r` around (x, y); look names up with `districtAt`. */
export interface District {
  readonly name: string
  readonly x: number
  readonly y: number
  readonly r: number
}

/** A placement: position and heading (radians from +x towards +y). */
export interface Spawn {
  readonly x: number
  readonly y: number
  readonly angle: number
}

/** How a vehicle settles on its wheels on a parked spot: its centre of mass's height (m a.s.l.), pitch and roll (rad). */
export type Rest = readonly [z: number, pitch: number, roll: number]

/**
 * A parked spot, with what the build baked from the terrain and walls there (src/sim/systems/spawn.ts
 * reads them; `bake.test.ts` checks they are current): the rest of each model that stands level
 * enough on it, and whether a truck fits (clear of the walls, and level).
 */
export interface ParkedSpot extends Spawn {
  readonly rest: Partial<Record<VehicleModel, Rest>>
  readonly truck?: true
}

/** A farm, baked by the build from the land cover (src/sim/population/farms.ts): its building (index into `MAP.buildings`), whether it is rural and whether pigs are kept by it. */
export interface FarmEntry {
  readonly building: number
  readonly rural: boolean
  readonly pen: boolean
}

/** A street lamp's lantern, baked by the build (src/render/sky/lamps.ts places them from the terrain): its centre (m, m a.s.l.), which way it faces and what holds it. */
export interface Lamp {
  readonly x: number
  readonly y: number
  readonly z: number
  readonly nx: number
  readonly ny: number
  readonly kind: "wall" | "pole"
}

/** The global map as the game reads it: the global file with its coarse grid decoded. */
export interface MonzoneMap {
  /** `MAP_VERSION` (`./packed.ts`): the decoders throw on any other. */
  readonly version: number
  /** The map's file name (`monzone`, `cesena`): its tiles are in the directory of that name beside it. */
  readonly name: string
  /** The build's hash (16 hex digits, over every file it wrote): each tile carries it, and one from another build is refused. */
  readonly hash: string
  readonly origin: { readonly lat: number; readonly lon: number }
  readonly mPerDeg: { readonly lat: number; readonly lon: number }
  readonly bounds: Bounds
  readonly heightmap: Heightmap
  /** Every tile with terrain in it, in key order (south to north, then west to east). */
  readonly tiles: ReadonlyArray<TileEntry>
  /** The map's place for the sky: its low ground (m a.s.l., the 5th percentile of its nodes) and the way its ground falls (rad). */
  readonly place: { readonly floor: number; readonly downslope: number }
  readonly coarse: Coarse
  readonly roads: ReadonlyArray<Road>
  readonly buildings: ReadonlyArray<Building>
  readonly water: ReadonlyArray<Water>
  readonly rail: ReadonlyArray<Rail>
  readonly railway: Railway
  readonly areas: ReadonlyArray<Area>
  readonly barriers: ReadonlyArray<Barrier>
  readonly pois: ReadonlyArray<Poi>
  readonly districts: ReadonlyArray<District>
  /** Road graph: `xy` node coords, `edges` flat (a, b, roadIndex) triples, `traffic`/`walk` edge indices. Use `graph` instead. */
  readonly graph: {
    readonly xy: ReadonlyArray<number>
    readonly edges: ReadonlyArray<number>
    readonly traffic: ReadonlyArray<number>
    readonly walk: ReadonlyArray<number>
  }
  /**
   * The walls' broad phases: how far any wall reaches past its midpoint along either axis (m: a wall
   * lives in its midpoint's tile, so a query looks this far into the next), the south-west corner of
   * each kind's lattice and the trees' (the lowest corner of any of them, where the whole map's broad
   * phase put it: `./lattice.ts`), and how many walk and drive walls there are (a shore wall's index in
   * the land and traffic broad phases follows them).
   */
  readonly walls: {
    readonly reach: number
    readonly lattice: Readonly<Record<WallKind | "trees", readonly [number, number]>>
    readonly counts: { readonly walk: number; readonly drive: number }
  }
  readonly spawns: { readonly player: Spawn; readonly parked: ReadonlyArray<ParkedSpot> }
  /**
   * Baked by the build (src/sim/lanes.ts; `bake.test.ts` checks they are current): per model, the lane
   * offset of each traffic edge (`graph.traffic` order) travelled b → a, then a → b; −1 where the model
   * may not drive it.
   */
  readonly lanes: Readonly<Record<VehicleModel, ReadonlyArray<number>>>
  readonly farms: ReadonlyArray<FarmEntry>
  readonly lamps: ReadonlyArray<Lamp>
}

/** Shape of the JSON line that opens the global file: the coarse grid's heights and cover travel as packed sections after it (see `./packed.ts`). */
export interface MonzoneMapJson extends Omit<MonzoneMap, "coarse"> {
  readonly coarse: Omit<Coarse, "heights" | "cover">
}

/** The road's class; the build only emits `ROAD_CLASSES` (checked by map.test.ts), anything else reads as "path". */
export const roadClassOf = (road: Road): RoadClass => (isRoadClass(road.cls) ? road.cls : "path")

const buildingStyles: ReadonlySet<string> = new Set(BUILDING_STYLES)
const isBuildingStyle = (style: string): style is BuildingStyle => buildingStyles.has(style)
/** The building's facade style; the build only emits `BUILDING_STYLES`, anything else reads as "plaster". */
export const buildingStyleOf = (building: Building): BuildingStyle =>
  isBuildingStyle(building.style) ? building.style : "plaster"

/**
 * HUD location name at (x, y): of the districts whose disc contains the point, the one it is
 * relatively closest to (distance / r); outside every disc, the district whose rim is nearest.
 */
export const districtAt = (x: number, y: number): District => {
  let best = MAP.districts[0]!,
    score = Number.MAX_VALUE
  for (const d of MAP.districts) {
    const dist = Math.sqrt((x - d.x) * (x - d.x) + (y - d.y) * (y - d.y))
    const s = dist <= d.r ? dist / d.r : 1 + dist - d.r
    if (s < score) [best, score] = [d, s]
  }
  return best
}

const hm = MAP.heightmap
const { minX, minY, maxX, maxY } = MAP.bounds

/** Scratch for the four nodes of a cell. */
const corners = new Int32Array(4)

/** Bilinear terrain elevation (m) at (x, y), clamped to the map bounds. */
export const heightAt = (x: number, y: number): number => {
  const fx = (Math.min(maxX, Math.max(minX, x)) - hm.x0) / hm.cell
  const fy = (Math.min(maxY, Math.max(minY, y)) - hm.y0) / hm.cell
  const i = Math.min(hm.cols - 2, Math.max(0, Math.floor(fx)))
  const j = Math.min(hm.rows - 2, Math.max(0, Math.floor(fy)))
  const tx = fx - i
  const ty = fy - j
  const [sw, se, nw, ne] = cellNodes(i, j, corners)
  const south = sw! + (se! - sw!) * tx
  const north = nw! + (ne! - nw!) * tx
  return (south + (north - south) * ty) / 10
}

/** Bounding box [minX, minY, maxX, maxY] of every building's outer ring, indexed like `MAP.buildings`. */
export const buildingBoxes: ReadonlyArray<readonly [number, number, number, number]> =
  MAP.buildings.map(({ outer }) => {
    let x0 = outer[0]!,
      y0 = outer[1]!,
      x1 = x0,
      y1 = y0
    for (let k = 2; k + 1 < outer.length; k += 2)
      [x0, y0, x1, y1] = [
        Math.min(x0, outer[k]!),
        Math.min(y0, outer[k + 1]!),
        Math.max(x1, outer[k]!),
        Math.max(y1, outer[k + 1]!),
      ]
    return [x0, y0, x1, y1] as const
  })

/**
 * Building broad phase (`staticGrid` over `buildingBoxes`, 64 m cells): calls `visit` with the
 * index into `MAP.buildings` of every building whose box may overlap the query box (run the exact
 * test). Shared by the sim and the audio host; `visit` must not query again.
 */
export const buildingsIn = staticGrid(buildingBoxes.length, (i) => buildingBoxes[i]!, 64)

/**
 * A straight graph edge. a -> b follows the vertex order of `MAP.roads[road].pts` (the OSM way
 * direction), so a `oneway` road may only be driven from a to b.
 */
interface GraphEdge {
  readonly a: number
  readonly b: number
  /** Index into `MAP.roads`. */
  readonly road: number
  /** Straight length a-b, m (edges are at most ~25 m). */
  readonly length: number
}

/**
 * Road network for AI steering. Junctions come from shared OSM nodes; long edges are split so
 * none exceeds ~25 m. Where a road leaves the play area its dead end sits 8 m inside the bounds,
 * beyond the road-exit caps: treat those degree-1 nodes as exits (despawn or U-turn).
 */
interface RoadGraph {
  readonly nodes: ReadonlyArray<{ readonly x: number; readonly y: number }>
  readonly edges: ReadonlyArray<GraphEdge>
  /** node -> incident edge indices */
  readonly adjacency: ReadonlyArray<ReadonlyArray<number>>
  /**
   * Edges AI cars may use: tertiary..service, public, one connected component. Where a lane
   * crosses a footprint the house is clipped to ~2.4 m around it, so keep vehicles wider than
   * ~2.2 m on tertiary/unclassified roads (`lanesFor` in route.ts fits each model to the walls).
   */
  readonly trafficEdges: ReadonlyArray<number>
  /** Edges pedestrians may use: every class but tunnels, one connected component. */
  readonly walkEdges: ReadonlyArray<number>
}

const buildGraph = (): RoadGraph => {
  const { xy, edges: flat, traffic, walk } = MAP.graph
  const nodes: Array<{ readonly x: number; readonly y: number }> = []
  for (let i = 0; i + 1 < xy.length; i += 2) nodes.push({ x: xy[i]!, y: xy[i + 1]! })
  const adjacency: Array<Array<number>> = nodes.map(() => [])
  const edges: Array<GraphEdge> = []
  for (let i = 0; i + 2 < flat.length; i += 3) {
    const a = flat[i]!,
      b = flat[i + 1]!
    const dx = nodes[b]!.x - nodes[a]!.x,
      dy = nodes[b]!.y - nodes[a]!.y
    adjacency[a]!.push(edges.length)
    adjacency[b]!.push(edges.length)
    edges.push({ a, b, road: flat[i + 2]!, length: Math.sqrt(dx * dx + dy * dy) })
  }
  return { nodes, edges, adjacency, trafficEdges: traffic, walkEdges: walk }
}

/** The road graph, rebuilt from shared OSM nodes at build time. */
export const graph: RoadGraph = buildGraph()
